  Lemma kwordv1_of_mem : forall E M (e : expr) (a : word) off (i : nat) (z : Z),
    edenot E e = a -> ev E i = Z_to_bv 64 z -> (0 <= z < 256)%Z ->
    (0 <= bv_unsigned a + off)%Z -> (bv_unsigned a + off + 1 <= 2 ^ 64)%Z ->
    M (Z_to_bv 64 (bv_unsigned a + off)) = Some (Z_to_bv 8 z) ->
